{
  "decision": "accept",
  "icd10_code": "E11.22",
  "code_display": "Type 2 DM with diabetic CKD",
  "guideline_citations": [
    {
      "url": "https://www.cms.gov/files/document/fy-2027-icd-10-cm-coding-guidelines.pdf",
      "quote": "The classification presumes a causal relationship between the two conditions linked by these terms in the Alphabetic Index or Tabular List. These conditions should be coded as related even in the absence of provider documentation explicitly linking them, unless the documentation clearly states the conditions are unrelated or when another guideline exists that specifically requires a documented linkage between two conditions (e.g., sepsis guideline for “acute organ dysfunction that is not clearly associated with the sepsis”).",
      "source": "CMS FY 2027 ICD-10-CM Official Guidelines for Coding and Reporting"
    }
  ],
  "rationale": "The chart contains verbatim statements confirming both conditions as active: 'Type 2 diabetes mellitus.', 'Chronic kidney disease stage 3.', 'Assessment: type 2 diabetes mellitus with hyperglycemia, currently active.', and 'Chronic kidney disease stage 3 is active.' No negation, family history, screening, hypothetical, or resolved language appears in the mention windows. The ICD-10-CM guideline presumes a causal link between diabetes and CKD for combination code E11.22 unless the record explicitly states they are unrelated, which it does not. The documented CKD diagnosis ('Chronic kidney disease stage 3') satisfies the requirement for a documented CKD diagnosis per N18 rules. Therefore, the combination code is supported.",
  "physician_query_needed": false
}
